content.content:
### source_lineage
{
 "type": "object",
 "required": [
  "origin_kind",
  "source_plugin",
  "source_path",
  "source_version",
  "source_digest",
  "imported_at"
 ],
 "properties": {
  "origin_kind": {
   "type": "string",
   "enum": [
    "manual",
    "github",
    "system-spec-harness",
    "system-dev-planner",
    "generated"
   ]
  },
  "source_plugin": {
   "type": [
    "string",
    "null"
   ]
  },
  "source_path": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
  },
  "source_version": {
   "type": [
    "string",
    "null"
   ]
  },
  "source_digest": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^[a-f0-9]{64}$"
  },
  "imported_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  }
 },
 "additionalProperties": false,
 "description": "引用・import元を追跡し、C19およびexternal plugin system-dev-planner由来のimportが外部正本を利用したことを検証する"
}

### confirmation_evidence
{
 "type": "object",
 "required": [
  "evaluator",
  "evidence_ref",
  "evaluated_digest"
 ],
 "properties": {
  "evaluator": {
   "type": [
    "string",
    "null"
   ]
  },
  "evidence_ref": {
   "type": [
    "string",
    "null"
   ]
  },
  "evaluated_digest": {
   "type": [
    "string",
    "null"
   ],
   "pattern": "^[a-f0-9]{64}$"
  }
 },
 "additionalProperties": false,
 "description": "confirmation/evaluationを同一artifact digestへpinしstale PASSを拒否する"
}

### confirmation_status
{
 "type": "string",
 "enum": [
  "draft",
  "confirmed",
  "superseded"
 ],
 "description": "内容確定状態。system plan入力はspecification/architectureがconfirmedであることを要求する"
}

### evaluation_status
{
 "type": "string",
 "enum": [
  "pending",
  "pass",
  "fail",
  "stale"
 ],
 "description": "独立評価状態。C14/C15/C04はpass以外をIssue起票・推薦・実装handoff対象にしない"
}

### implementation_readiness
{
 "type": "object",
 "required": [
  "status",
  "missing_sections",
  "checked_at"
 ],
 "properties": {
  "status": {
   "type": "string",
   "enum": [
    "complete",
    "incomplete",
    "not_applicable"
   ]
  },
  "missing_sections": {
   "type": "array",
   "items": {
    "type": "string"
   },
   "uniqueItems": true
  },
  "checked_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  }
 },
 "additionalProperties": false,
 "description": "template-contract.jsonの必須field/section、placeholder、conditional template、参照解決を検査した実装着手準備状態"
}

### tracker_binding
{
 "type": "string",
 "enum": [
  "beads",
  "github",
  "none",
  "repo-config-default"
 ],
 "description": "issue_linkageと対称のtracker択一宣言。beads=bd issueとして実行管理、github=GitHub Issueとして実行管理、none=どちらにも投影しない。repo-config-default=登録搬送時のみの遅延束縛sentinel (dev-graph-registration payloadが搬送し、C02がatomic登録時に.dev-graph/config.jsonのexecution_trackerから解決する。永続ノードには現れてはならず、残存はC11がfail-closed検査する)。単一publication authority (references/execution-tracker-contract.md §4) の起点で、github_publication.modeとの排他はallOfでfail-closed検査する"
}

### github_publication
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "mode",
  "project_aliases",
  "labels",
  "milestone"
 ],
 "properties": {
  "mode": {
   "type": "string",
   "enum": [
    "local_only",
    "issue",
    "issue_and_projects"
   ]
  },
  "project_aliases": {
   "type": "array",
   "uniqueItems": true,
   "items": {
    "type": "string",
    "minLength": 1
   }
  },
  "labels": {
   "type": "array",
   "uniqueItems": true,
   "items": {
    "type": "string",
    "minLength": 1
   }
  },
  "milestone": {
   "type": [
    "string",
    "null"
   ]
  }
 },
 "description": "task specification確定後の外部publication intent。project_aliases空かつmode=issue_and_projectsの場合はrepo configのdefault/auto-add targetを使う。draft/unconfirmed/evaluation非pass/readiness非completeではmodeに関わらず外部write禁止。"
}

### issue_linkage
{
 "type": [
  "object",
  "null"
 ],
 "description": "GitHub Issue との紐付け。C14 (decompose) が起票した時点でissue_numberを書き込み、C03 (sync) はlinkage済みノードを新規起票せずupdated_at比較のみを行う (create→syncの起票非重複契約・要件C7)",
 "properties": {
  "issue_number": {
   "type": "integer"
  },
  "repo": {
   "type": "string"
  },
  "linked_at": {
   "type": "string",
   "format": "date-time"
  }
 },
 "required": [
  "issue_number",
  "repo"
 ]
}

### beads_linkage
{
 "type": [
  "object",
  "null"
 ],
 "description": "bd issueとの紐付け。issue_linkageと対称に、C28 (bd-bridge) の起票結果を受けてC02経由で記録する可変projection。以後は冪等upsertのsync_state更新だけを行う (external_ref=graph_node_idが冪等キー)。未起票 (unlinked) はbeads_linkage=nullで表現し、sync_state enumには含めない",
 "additionalProperties": false,
 "properties": {
  "bd_issue_id": {
   "type": "string",
   "minLength": 1
  },
  "linked_at": {
   "type": "string",
   "format": "date-time"
  },
  "sync_state": {
   "type": "string",
   "enum": [
    "linked",
    "synced",
    "pending_retry",
    "conflict"
   ]
  },
  "github_mirror": {
   "type": [
    "object",
    "null"
   ],
   "additionalProperties": false,
   "required": [
    "repo",
    "issue_number",
    "sync_direction",
    "linked_at"
   ],
   "properties": {
    "repo": {
     "type": "string",
     "pattern": "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"
    },
    "issue_number": {
     "type": "integer",
     "minimum": 1
    },
    "sync_direction": {
     "const": "beads_to_github_push_only"
    },
    "linked_at": {
     "type": "string",
     "format": "date-time"
    }
   },
   "description": "bd github sync --push-onlyが作ったviewer用Issue identity。C12はIssue mutationせずPR marker/Projects auto-add照合だけに使う"
  }
 },
 "required": [
  "bd_issue_id",
  "linked_at",
  "sync_state"
 ]
}

### execution_contexts
{
 "type": "array",
 "items": {
  "type": "object",
  "additionalProperties": false,
  "required": [
   "worktree_id",
   "branch",
   "base_branch",
   "head_sha",
   "state",
   "lease_acquired_at",
   "last_seen_at",
   "released_at"
  ],
  "properties": {
   "worktree_id": {
    "type": "string",
    "pattern": "^wt_[0-9a-f]{16}$"
   },
   "branch": {
    "type": [
     "string",
     "null"
    ]
   },
   "base_branch": {
    "type": "string",
    "minLength": 1
   },
   "head_sha": {
    "type": "string",
    "pattern": "^[0-9a-f]{40}$"
   },
   "state": {
    "type": "string",
    "enum": [
     "claimed",
     "in_progress",
     "pending_review",
     "pending_merge",
     "merged",
     "released",
     "expired"
    ]
   },
   "lease_acquired_at": {
    "type": [
     "string",
     "null"
    ],
    "format": "date-time"
   },
   "last_seen_at": {
    "type": "string",
    "format": "date-time"
   },
   "released_at": {
    "type": [
     "string",
     "null"
    ],
    "format": "date-time"
   }
  }
 },
 "description": "git common dirのephemeral lease registryからdefault branch側で収束したdurable projection。worktree絶対pathやsession secretは保持しない。"
}

### completion_evidence
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "policy",
  "status",
  "source",
  "completed_at",
  "reconciled_at",
  "evidence_refs"
 ],
 "properties": {
  "policy": {
   "type": "string",
   "enum": [
    "manual",
    "linked_pr_merged_all",
    "linked_pr_merged_any",
    "issue_closed"
   ]
  },
  "status": {
   "type": "string",
   "enum": [
    "open",
    "in_progress",
    "blocked",
    "done",
    "not_applicable"
   ]
  },
  "source": {
   "type": [
    "string",
    "null"
   ],
   "enum": [
    null,
    "github_pr_merge",
    "github_issue_close",
    "github_issue_reopen",
    "manual",
    "reconciliation"
   ]
  },
  "completed_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  },
  "reconciled_at": {
   "type": [
    "string",
    "null"
   ],
   "format": "date-time"
  },
  "evidence_refs": {
   "type": "array",
   "uniqueItems": true,
   "items": {
    "type": "string",
    "minLength": 1
   }
  }
 }
}

### resource_scope
{
 "type": "array",
 "items": {
  "type": "string",
  "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
 },
 "description": "touches: このノードが触るファイル/ディレクトリパス配列。既定はディレクトリ単位、ノードがファイル単位を明示した場合はファイル単位を優先し、双方混在時は広い方(ディレクトリ単位)へフォールバックする。並列バッチのresource_scope重複回避(要件C10)の土台"
}

